import { Data, Effect, Schema as S } from "effect"

const Artifact = S.Struct({
  packageName: S.String,
  version: S.String
})

export interface ReleaseNotes {
  readonly artifact: typeof Artifact.Type
  readonly body: string
}

export class InvalidReleaseNotes extends Data.TaggedError("InvalidReleaseNotes")<{
  readonly reason: string
  readonly header: string
}> {}

export const parseReleaseNotes = (
  source: string
): Effect.Effect<ReleaseNotes, InvalidReleaseNotes> =>
  Effect.gen(function*() {
    const [header = "", separator, ...bodyLines] = source.split("\n")

    if (separator !== "") {
      return yield* new InvalidReleaseNotes({
        reason: "Expected a blank line between the artifact header and release notes",
        header
      })
    }

    const match = /^artifact:(.*)@(.*)$/.exec(header)
    if (match === null) {
      return yield* new InvalidReleaseNotes({
        reason: "Expected an artifact header containing a package and version",
        header
      })
    }

    return {
      artifact: { packageName: match[1]!, version: match[2]! },
      body: bodyLines.join("\n")
    }
  })

compliant:
import { Data, Effect, Schema as S } from "effect"

const Artifact = S.Struct({
  packageName: S.String,
  version: S.String
})

const ArtifactHeader = S.String.pipe(
  S.decodeTo(S.TemplateLiteralParser(["artifact:", S.String, "@", S.String]))
)

export interface ReleaseNotes {
  readonly artifact: typeof Artifact.Type
  readonly body: string
}

export class InvalidReleaseNotes extends Data.TaggedError("InvalidReleaseNotes")<{
  readonly reason: string
  readonly header: string
}> {}

export const parseReleaseNotes = (
  source: string
): Effect.Effect<ReleaseNotes, InvalidReleaseNotes> =>
  Effect.gen(function*() {
    const [header = "", separator, ...bodyLines] = source.split("\n")

    if (separator !== "") {
      return yield* new InvalidReleaseNotes({
        reason: "Expected a blank line between the artifact header and release notes",
        header
      })
    }

    const [, packageName, , version] = yield* S.decodeEffect(ArtifactHeader)(header).pipe(
      Effect.mapError(() => new InvalidReleaseNotes({
        reason: "Expected an artifact header containing a package and version",
        header
      }))
    )

    return {
      artifact: { packageName, version },
      body: bodyLines.join("\n")
    }
  })
